  if (channel === 'incidents:update') { const user = permit('ADMIN','OPERATOR','USER'); return db.transaction(() => { const before = one(db,'SELECT * FROM incidents WHERE id=?',p.id); if (!before) throw new Error('접수 건을 찾을 수 없습니다.'); if (user.role === 'USER' && (before.reported_by !== user.id || before.status !== 'RECEIVED')) throw new Error('권한이 없습니다.'); db.prepare('UPDATE incidents SET title=?,category=?,severity=?,description=?,department=?,intake_source=COALESCE(?,intake_source),reporter_name=?,equipment_name=?,service_impact=?,desired_resolution_at=?,updated_at=? WHERE id=?').run(p.title,p.category,p.severity,p.description,p.department ?? null,p.intakeSource ?? null,p.reporterName ?? null,p.equipmentName ?? null,p.serviceImpact ?? null,p.desiredResolutionAt ?? null,now(),p.id); db.prepare('INSERT INTO incident_events (id,incident_id,event_type,from_status,to_status,note,actor_id,created_at,metadata_json) VALUES (?,?,?,?,?,?,?,?,?)').run(randomUUID(),p.id,'UPDATED',before.status,before.status,'접수 내용 수정',user.id,now(),JSON.stringify({ changed:true })); audit(db,'UPDATE','incidents',String(p.id),before,p); return true })() }
