  if (channel === 'system:setOperationsSettings') { permit('ADMIN'); return db.transaction(() => { const before={ planTime:setting(db,'daily_plan_time','08:30'),closeTime:setting(db,'daily_close_time','16:00'),urgentSlaMinutes:setting(db,'sla_urgent_minutes','60'),normalSlaMinutes:setting(db,'sla_normal_minutes','480') }; for (const [key,value] of [['daily_plan_time',p.planTime],['daily_close_time',p.closeTime],['sla_urgent_minutes',String(p.urgentSlaMinutes)],['sla_normal_minutes',String(p.normalSlaMinutes)]]) db.prepare('INSERT INTO app_settings(key,value,updated_at) VALUES (?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at').run(key,value,now()); audit(db,'UPDATE','app_settings','operations',before,p); return true })() }
  if (channel === 'system:auditLogs') { permit('ADMIN'); return all(db,'SELECT * FROM audit_logs ORDER BY created_at DESC LIMIT ?',p.limit) }
